/**
 * Turns research/company-questions.json into per-topic data files the site renders as
 * "Reported in interviews at …" with links to the original posts.
 *
 *   npx tsx scripts/research/apply-reports.ts        (after analyze.ts)
 *
 * Output: src/content/reports/<track>/<topic>.yaml — generated, do not edit by hand.
 * Topics listed in research/topic-map.json that don't exist yet are skipped.
 */
import { access, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { stringify } from 'yaml';

interface Report {
  year: number;
  month: number;
  title: string;
  source: string;
}
interface Entry {
  company: string;
  topic: string;
  reports: Report[];
}

const root = new URL('../../', import.meta.url).pathname;
const MAX_COMPANIES = 15;
const MAX_SOURCES = 3;

const exists = (p: string) =>
  access(p).then(
    () => true,
    () => false,
  );

async function main() {
  const { meta, entries } = JSON.parse(
    await readFile(join(root, 'research/company-questions.json'), 'utf8'),
  ) as {
    meta: { generatedAt: string; source: string; window: string };
    entries: Entry[];
  };
  const topicMap: Record<string, string[]> = JSON.parse(
    await readFile(join(root, 'research/topic-map.json'), 'utf8'),
  );

  // topicId → company → reports (deduplicated by source URL)
  const byTopic = new Map<string, Map<string, Map<string, Report>>>();
  for (const e of entries) {
    for (const topicId of topicMap[e.topic] ?? []) {
      const companies = byTopic.get(topicId) ?? new Map<string, Map<string, Report>>();
      const reports = companies.get(e.company) ?? new Map<string, Report>();
      for (const r of e.reports) reports.set(r.source, r);
      companies.set(e.company, reports);
      byTopic.set(topicId, companies);
    }
  }

  const outDir = join(root, 'src/content/reports');
  await rm(outDir, { recursive: true, force: true });
  let written = 0;
  const skipped: string[] = [];

  for (const [topicId, companies] of [...byTopic.entries()].sort()) {
    if (!(await exists(join(root, 'src/content/topics', topicId, 'index.mdx')))) {
      skipped.push(topicId);
      continue;
    }
    const list = [...companies.entries()]
      .map(([company, reports]) => {
        const sorted = [...reports.values()].sort((a, b) => b.year - a.year || b.month - a.month);
        return {
          company,
          reports: sorted.length,
          latestYear: sorted[0]!.year,
          sources: sorted
            .slice(0, MAX_SOURCES)
            .map((r) => ({ url: r.source, title: r.title.slice(0, 140), year: r.year })),
        };
      })
      .sort(
        (a, b) =>
          b.reports - a.reports ||
          b.latestYear - a.latestYear ||
          a.company.localeCompare(b.company),
      )
      .slice(0, MAX_COMPANIES);

    const file = join(outDir, `${topicId}.yaml`);
    await mkdir(dirname(file), { recursive: true });
    await writeFile(
      file,
      `# Generated by scripts/research/apply-reports.ts on ${meta.generatedAt} — do not edit.\n` +
        stringify(
          {
            generatedAt: meta.generatedAt,
            source: meta.source,
            window: meta.window,
            companies: list,
          },
          { lineWidth: 0 },
        ),
    );
    written++;
  }
  console.log(`Wrote ${written} report files. Skipped (topic not written yet): ${skipped.length}`);
  if (skipped.length) console.log(skipped.join(', '));
}

await main();
